            ['start_time'=>1123.04,'end_time'=>1123.9,'target_text'=>'Know, it is a lot of fun.','source_text'=>'Saya memang sukakannya.','order'=>496],
            ['start_time'=>1124,'end_time'=>1124.94,'target_text'=>'I do like it.','source_text'=>'>> Sememangnya.','order'=>497],
            ['start_time'=>1125.04,'end_time'=>1125.58,'target_text'=>'>> Definitely.','source_text'=>'>> Nampaknya Leon tak dapat keluarkan wang tunai tadi.','order'=>498],
